// GERADO por scripts/sincronizar-documentacao.mjs — não editar à mão.
export const HTML: string = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>FNI — Documentação funcional e de APIs</title>\n<link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<style>\n:root{--azul:#0b3d91;--azul2:#1d5fd1;--bg:#f6f8fb;--card:#fff;--bd:#dfe5ee;--tx:#1b2433;--mut:#5b6b82;--ok:#157347;--warn:#b26a00;--bad:#b42318;--code:#f0f3f8}\n*{box-sizing:border-box}\nbody{margin:0;font:15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--tx);background:var(--bg)}\naside{position:fixed;inset:0 auto 0 0;width:290px;background:#0f1b33;color:#cfd8e8;overflow:auto;padding:18px 0 40px}\naside h1{font-size:15px;margin:0 18px 4px;color:#fff}\naside .sub{margin:0 18px 12px;font-size:12px;color:#8fa1c0}\naside input{width:calc(100% - 36px);margin:0 18px 12px;padding:7px 10px;border-radius:6px;border:0;font-size:13px}\naside .grp{margin:14px 18px 4px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#7f93b8}\naside a{display:block;padding:4px 18px 4px 22px;color:#cfd8e8;text-decoration:none;font-size:13.5px;border-left:3px solid transparent}\naside a:hover{background:#17274a;border-left-color:var(--azul2);color:#fff}\naside a.sub2{padding-left:36px;font-size:12.5px;color:#a9b8d3}\nmain{margin-left:290px;padding:28px 44px 80px;max-width:1180px}\nh1.t{font-size:28px;margin:0 0 4px;color:var(--azul)}\nh2{font-size:22px;margin:44px 0 10px;padding-top:14px;border-top:2px solid var(--bd);color:var(--azul)}\nh3{font-size:17px;margin:28px 0 6px}\nh4{font-size:14px;margin:18px 0 4px;color:var(--mut);text-transform:uppercase;letter-spacing:.04em}\np,li{max-width:920px}\n.card{background:var(--card);border:1px solid var(--bd);border-radius:10px;padding:14px 18px;margin:14px 0}\n.note{border-left:4px solid var(--azul2);background:#eaf1ff;padding:10px 14px;border-radius:6px;margin:12px 0}\n.warn{border-left-color:var(--warn);background:#fff4e0}\n.bad{border-left-color:var(--bad);background:#fdecea}\n.ok{border-left-color:var(--ok);background:#e8f6ee}\ntable{border-collapse:collapse;width:100%;margin:10px 0;background:var(--card);font-size:13.5px}\nth,td{border:1px solid var(--bd);padding:6px 9px;text-align:left;vertical-align:top}\nth{background:#eef2f9;font-weight:600}\ncode{background:var(--code);padding:1px 5px;border-radius:4px;font:12.5px ui-monospace,Menlo,Consolas,monospace}\npre{background:#0f1b33;color:#e6edf7;padding:12px 14px;border-radius:8px;overflow:auto;font:12.5px/1.5 ui-monospace,Menlo,Consolas,monospace}\npre.mermaid{background:#fff;color:inherit;border:1px solid var(--bd);text-align:center;padding:14px}\n.badge{display:inline-block;font-size:11px;padding:1px 7px;border-radius:10px;background:#e6edf7;color:var(--azul);margin-right:4px;font-weight:600}\n.get{background:#e1f3ea;color:var(--ok)}.post{background:#e3ecff;color:var(--azul2)}.rpc{background:#f1e8fb;color:#6b2fb3}\n.ep{border:1px solid var(--bd);border-radius:10px;background:#fff;margin:16px 0;overflow:hidden}\n.ep .hd{padding:9px 14px;background:#f3f6fb;border-bottom:1px solid var(--bd);font-weight:600}\n.ep .bd{padding:4px 16px 12px}\n.toc{columns:2;gap:30px}\n.mut{color:var(--mut)}\n@media(max-width:900px){aside{position:static;width:auto}main{margin:0;padding:18px}.toc{columns:1}}\n@media print{aside{display:none}main{margin:0}}\n.logo-fni{display:block;height:54px;width:auto;background:#fff;border-radius:10px;padding:6px 12px;box-shadow:0 1px 3px rgba(0,0,0,.18);margin:0 0 14px}\naside .logo-fni{height:46px;margin:0 18px 12px}\nmain .logo-fni{height:60px;margin:0 0 10px;box-shadow:none;padding:0;background:none}\n</style>\n</head>\n<body>\n<aside>\n<img class=\"logo-fni\" alt=\"FNI — Fleet Network Intelligence\" src=\"data:image/png;base64,\">\n<h1>FNI</h1>\n<div class=\"sub\">Documentação funcional e de APIs · 05/10/2026</div>\n<input id=\"busca\" placeholder=\"Filtrar o menu…\" oninput=\"filtra(this.value)\">\n<div class=\"grp\">Parte 1 · Funcional</div>\n<a href=\"#visao\">1. Visão geral e perfis</a>\n<a href=\"#pdv\">2. PDV FNI (posto)</a>\n<a class=\"sub2\" href=\"#pdv-abastecer\">Abastecimento ponta a ponta</a>\n<a class=\"sub2\" href=\"#pdv-negado\">Negado por regra e liberação</a>\n<a class=\"sub2\" href=\"#pdv-prepedido\">Pré-Pedido</a>\n<a class=\"sub2\" href=\"#pdv-resgate\">Resgate de voucher</a>\n<a class=\"sub2\" href=\"#pdv-ajuste\">Pedido de ajuste</a>\n<a class=\"sub2\" href=\"#pdv-hodometro\">Hodômetro e antifraude</a>\n<a class=\"sub2\" href=\"#pdv-extrato\">Extrato, dashboard e telas</a>\n<a href=\"#web\">3. Painel web Gestão de Frotas</a>\n<a class=\"sub2\" href=\"#web-acesso\">Acesso, perfis e permissões</a>\n<a class=\"sub2\" href=\"#web-abast\">Abastecimentos e importações</a>\n<a class=\"sub2\" href=\"#web-parametros\">Parâmetros de uso e antifraude</a>\n<a class=\"sub2\" href=\"#web-neg\">Negociação com postos</a>\n<a class=\"sub2\" href=\"#web-fid\">Fidelidade e resgates</a>\n<a class=\"sub2\" href=\"#web-nf\">Notas fiscais</a>\n<a class=\"sub2\" href=\"#web-fin\">Financeiro e conciliação</a>\n<a class=\"sub2\" href=\"#web-rede\">Inteligência de rede e ANP</a>\n<a class=\"sub2\" href=\"#web-assin\">Assinaturas e cobrança</a>\n<a class=\"sub2\" href=\"#web-outros\">Demais módulos</a>\n<a href=\"#mot\">4. PWA Motorista</a>\n<a href=\"#cli\">5. PWA Cliente</a>\n<div class=\"grp\">Parte 2 · APIs</div>\n<a href=\"#api-conv\">6. Convenções e autenticação</a>\n<a href=\"#api-ext\">7. API externa (chave de API)</a>\n<a class=\"sub2\" href=\"#api-ext-lista\">Catálogo de endpoints</a>\n<a class=\"sub2\" href=\"#api-ext-detalhe\">Detalhe dos principais</a>\n<a href=\"#api-int\">8. Rotas internas do painel</a>\n<a href=\"#api-rpc\">9. RPCs Supabase</a>\n<a class=\"sub2\" href=\"#rpc-pdv\">RPCs do PDV</a>\n<a class=\"sub2\" href=\"#rpc-base\">RPCs de base</a>\n<a href=\"#api-edge\">10. Edge Functions</a>\n<a href=\"#api-cron\">11. Rotinas agendadas</a>\n<a href=\"#api-terc\">12. Integrações externas</a>\n<a href=\"#glossario\">13. Glossário e pendências</a>\n</aside>\n<main>\n<img class=\"logo-fni\" alt=\"FNI — Fleet Network Intelligence\" src=\"data:image/png;base64,\">\n<h1 class=\"t\">FNI — Documentação funcional e de APIs</h1>\n<p class=\"mut\">Gerada em 05/10/2026 a partir do código dos quatro projetos e do banco Supabase de produção. Os diagramas são Mermaid e precisam de internet para carregar a biblioteca. Complementa o <em>C4 Model</em> (<a href=\"/documentacao/arquitetura\"><code>Arquitetura FNI</code></a>), que descreve a estrutura; este documento descreve o comportamento.</p>\n\n<div class=\"card toc\"><b>Como ler</b><br>\nParte 1 explica o que cada funcionalidade faz, para quem, e desenha o fluxo. Parte 2 é referência técnica: quem autentica como, quais endpoints existem, quais RPCs o PDV chama e em que ordem.<br><br>\n<b>Escopo de profundidade:</b> os fluxos principais (PDV, abastecimentos, permissões, integrações) estão detalhados. Módulos de menor uso do painel web têm descrição curta na seção <a href=\"#web-outros\">Demais módulos</a>.</div>\n\n<h2 id=\"visao\">1. Visão geral e perfis</h2>\n<p>O ecossistema tem quatro aplicações em cima de um único banco Supabase (Postgres com RLS, RPCs, Realtime, pg_cron e Edge Functions):</p>\n<table>\n<tr><th>Aplicação</th><th>Tecnologia</th><th>Quem usa</th><th>Para que serve</th></tr>\n<tr><td>Painel web <b>Gestão de Frotas</b></td><td>Next.js (Railway)</td><td>Admin FNI, gestor e equipe do cliente, gestor do posto</td><td>Gestão completa de frota, rede de postos, financeiro, fidelidade, integrações.</td></tr>\n<tr><td><b>PDV FNI</b></td><td>Next.js (Railway)</td><td>Posto: gestor, colaborador, caixa</td><td>Frente de caixa do posto: valida abastecimento do motorista, registra bomba, fecha venda, queima voucher.</td></tr>\n<tr><td><b>PWA Motorista</b></td><td>Flutter web</td><td>Motorista</td><td>Abastecer no PDV, pontos, resgates, jornada, inspeção, fretes.</td></tr>\n<tr><td><b>PWA Cliente</b></td><td>Flutter web</td><td>Gestor/equipe do cliente (frota)</td><td>Painel móvel: indicadores, liberação de abastecimentos negados, avisos de pedidos de ajuste.</td></tr>\n</table>\n\n<h3>Perfis e níveis</h3>\n<table>\n<tr><th>Perfil</th><th>Nível</th><th>Visão</th><th>O que decide / pode</th></tr>\n<tr><td><code>admin</code></td><td>4</td><td>FNI (global)</td><td>Vê todos os clientes e postos; gerencia usuários de qualquer empresa; define os padrões globais de permissão para admin, gestor_frota e posto.</td></tr>\n<tr><td><code>gestor_frota</code></td><td>3</td><td>Cliente (frota)</td><td>Dono da conta do cliente. Convida a equipe (entra como Analista) e decide em <em>Permissões</em> o que o Analista usa.</td></tr>\n<tr><td><code>analista</code></td><td>2</td><td>Cliente</td><td>Equipe operacional do cliente. Sem poderes globais (não lê todos os usuários nem gerencia usuários).</td></tr>\n<tr><td><code>posto</code></td><td>1</td><td>Posto (revenda)</td><td>Gestor do posto. Convida Colaborador ou Caixa e decide o que cada um usa.</td></tr>\n<tr><td><code>colaborador</code></td><td>0</td><td>Posto</td><td>Equipe do posto, conforme Permissões do gestor do posto.</td></tr>\n<tr><td><code>caixa</code></td><td>0</td><td>Posto</td><td>Operador do PDV. Padrão libera só as 8 telas do PDV; o resto do painel web fica bloqueado.</td></tr>\n</table>\n<div class=\"note\">Permissões ficam em <code>permissoes_perfil(funcionalidade, perfil, permitido, empresa_id)</code>. A empresa sentinela <code>00000000-0000-0000-0000-000000000000</code> guarda o padrão global. <b>Linha ausente significa permitido.</b> A aplicação é feita na interface e na proteção de rotas; não é uma barreira de banco para cada tabela. 97 funcionalidades estão catalogadas.</div>\n\n<h3>Mapa de relacionamento entre atores</h3>\n<pre class=\"mermaid\">\nflowchart LR\n  M[\"Motorista<br/>PWA Motorista\"] -->|\"inicia abastecimento<br/>código + OTP\"| DB[(\"Supabase<br/>RPCs + RLS\")]\n  P[\"Posto<br/>PDV FNI\"] -->|\"valida, lê bomba,<br/>conclui\"| DB\n  C[\"Cliente frota<br/>Painel web / PWA Cliente\"] -->|\"regras, liberação,<br/>ajustes, relatórios\"| DB\n  A[\"Admin FNI<br/>Painel web\"] -->|\"cadastros, planos,<br/>permissões globais\"| DB\n  DB -->|\"Realtime\"| M\n  DB -->|\"Realtime\"| P\n  DB -->|\"Realtime + e-mail\"| C\n  EXT[\"ERPs, cartões,<br/>GPS, ANP, Stripe\"] -->|\"API chave / cron / webhook\"| DB\n</pre>\n\n<h2 id=\"pdv\">2. PDV FNI (frente de caixa do posto)</h2>\n<p>Aplicação Next.js separada (<code>pdv-fni</code>), com login próprio (e MFA em <code>/mfa-setup</code>). Fala só com o Supabase por RPCs <code>SECURITY DEFINER</code>: toda RPC confere se o usuário pertence à revenda via <code>empresas_do_usuario(email)</code>.</p>\n<table>\n<tr><th>Tela</th><th>Rota</th><th>Função</th></tr>\n<tr><td>Validar</td><td><code>/validar</code></td><td>Seleciona a leitura de bomba, digita código do abastecimento e OTP do motorista.</td></tr>\n<tr><td>Abastecimento</td><td><code>/abastecimento/[id]</code></td><td>Acompanha e conclui a venda: itens extras, forma de pagamento, Resumo da venda.</td></tr>\n<tr><td>Extrato</td><td><code>/extrato</code></td><td>Lista paginada (20 por página) com busca por placa, motorista ou código; selo \"Em ajuste\".</td></tr>\n<tr><td>Ajustes</td><td><code>/ajustes</code></td><td>Pedidos de ajuste pendentes e histórico; aprovar, recusar (motivo obrigatório) ou cancelar.</td></tr>\n<tr><td>Resgates</td><td><code>/resgates</code></td><td>Valida e queima voucher de fidelidade.</td></tr>\n<tr><td>Pré-pedido</td><td><code>/pre-pedido</code></td><td>Informa o número do pré-pedido do motorista.</td></tr>\n<tr><td>Dashboard</td><td><code>/dashboard</code></td><td>Indicadores de uso e resgates (<code>metricas_pdv_dashboard</code>).</td></tr>\n<tr><td>Bicos, Produtos, Terminais</td><td><code>/bicos</code> <code>/produtos</code> <code>/terminais</code></td><td>Cadastros de bombas/bicos/combustíveis, catálogo de produtos e serviços, terminais do posto.</td></tr>\n</table>\n\n<h3 id=\"pdv-abastecer\">2.1 Abastecimento ponta a ponta</h3>\n<p><b>Objetivo:</b> o motorista abastece em um posto credenciado sem cartão. Ele inicia pelo celular, o posto confirma com um código e uma senha temporária (OTP), registra o que saiu da bomba e fecha a venda.</p>\n<pre class=\"mermaid\">\nsequenceDiagram\n  autonumber\n  actor Mot as Motorista (PWA)\n  participant DB as Supabase (RPCs)\n  actor Cx as Caixa (PDV)\n  Mot->>DB: buscar_revendas_pdv_proximas(lat, lon, raio)\n  DB-->>Mot: revendas próximas\n  Mot->>DB: iniciar_abastecimento_pdv(revenda, lat, lon, placa, hodômetro)\n  Note over DB: valida geolocalização, vínculo, hodômetro (server-side)<br/>cria abastecimentos_pdv, código = 4000000000 + id\n  DB-->>Mot: código do abastecimento\n  loop a cada 30 s\n    Mot->>DB: obter_otp_atual_pdv(id)\n    DB-->>Mot: OTP vigente e contador regressivo\n  end\n  Cx->>DB: listar_leituras_bomba_disponiveis_pdv(revenda)\n  Cx->>DB: validar_codigo_leitura_pdv(código, OTP, leitura, terminal)\n  DB-->>Cx: dados do abastecimento: placa, motorista, combustível, litros, valor\n  DB-->>Mot: Realtime: posto validou\n  Cx->>DB: listar_formas_pagamento_permitidas_pdv(id)\n  Cx->>DB: concluir_abastecimento_pdv(id, forma, itens)\n  Note over DB: avalia regras do cliente, forma permitida, itens\n  DB-->>Cx: confirmado + totais\n  DB-->>Mot: Realtime: confirmado\n  Note over DB: trigger creditar_pontos_abastecimento_pdv\n  Mot->>DB: avaliar_abastecimento_pdv(notas)\n</pre>\n<h4>Estados do abastecimento (<code>abastecimentos_pdv.status</code>)</h4>\n<pre class=\"mermaid\">\nstateDiagram-v2\n  [*] --> aguardando_pdv: motorista inicia (código + OTP)\n  aguardando_pdv --> confirmado: concluir_abastecimento_pdv ok\n  aguardando_pdv --> negado: regra do cliente, pré-pedido ou forma de pagamento\n  negado --> aguardando_pdv: gestor libera (OTP renovado por 10 min)\n  negado --> negado: gestor recusa\n  aguardando_pdv --> expirado: OTP vence sem conclusão\n  confirmado --> [*]\n</pre>\n<div class=\"note\">Valores permitidos em <code>abastecimentos_pdv.status</code> (constraint do banco): <code>aguardando_pdv</code>, <code>negado</code>, <code>confirmado</code>, <code>expirado</code>. O registro nasce em <code>aguardando_pdv</code>; a validação de código e OTP pelo posto não muda o status, ela associa a leitura de bomba (<code>valor_total_combustivel</code>) que habilita a conclusão.</div>\n<h4>Respostas de <code>concluir_abastecimento_pdv</code></h4>\n<table>\n<tr><th><code>status</code></th><th>Significado</th></tr>\n<tr><td><code>confirmado</code></td><td>Venda fechada. Devolve <code>codigoAbastecimento</code>, <code>valorTotalCombustivel</code>, <code>valorTotalItensExtra</code>, <code>valorTotalTransacao</code>.</td></tr>\n<tr><td><code>nao_encontrado</code> · <code>nao_autorizado</code></td><td>Id inexistente, ou usuário não pertence à revenda.</td></tr>\n<tr><td><code>leitura_bomba_pendente</code></td><td>Ainda não há valor de bomba registrado.</td></tr>\n<tr><td><code>negado</code> + <code>motivo</code></td><td><code>regras_cliente</code>, <code>pre_pedido_limite</code> ou <code>forma_pagamento_nao_permitida</code>. Grava <code>motivo_negacao</code> e <code>regras_violadas</code>.</td></tr>\n<tr><td><code>regras_violadas</code></td><td>Violações corrigíveis: o PDV mostra o que ajustar (ex.: item, forma) e tenta de novo, sem negar.</td></tr>\n<tr><td><code>item_invalido</code> + <code>motivo</code></td><td><code>quantidade_invalida</code> (≤ 0 ou mais de 3 casas) ou <code>somente_diesel</code> (item exclusivo de diesel num abastecimento de outro combustível).</td></tr>\n<tr><td>qualquer outro status</td><td>Devolve o status atual (idempotência: já confirmado, expirado etc.).</td></tr>\n</table>\n\n<h3 id=\"pdv-negado\">2.2 Negado por regra do cliente e liberação</h3>\n<p>Se a venda viola uma regra cadastrada pelo cliente em Parâmetros de uso (limite diário, intervalo, horário, produto etc.), o abastecimento fica <code>negado</code>. Motorista e posto ficam esperando enquanto o gestor do cliente decide. O pedido tem validade curta.</p>\n<pre class=\"mermaid\">\nsequenceDiagram\n  actor Cx as Caixa (PDV)\n  participant DB as Supabase\n  actor G as Gestor do cliente\n  Cx->>DB: concluir_abastecimento_pdv\n  DB-->>Cx: negado (regras_cliente) + violações\n  DB-->>G: bolinha no menu, aviso flutuante, banner no PWA Cliente\n  G->>DB: listar_abastecimentos_negados_pdv(empresa)\n  G->>DB: decidir_abastecimento_negado_pdv(id, liberado ou recusado, justificativa)\n  alt liberado\n    DB-->>Cx: Realtime: status volta a aguardando_pdv, avaliação de regras é pulada\n    Cx->>DB: concluir_abastecimento_pdv\n    DB-->>Cx: confirmado\n  else recusado ou vencido\n    DB-->>Cx: permanece negado\n  end\n</pre>\n<table>\n<tr><th>Resposta de <code>decidir_abastecimento_negado_pdv</code></th><th>Quando</th></tr>\n<tr><td><code>liberado</code> · <code>recusado</code></td><td>Decisão gravada (<code>liberacao_decisao</code>, <code>_decidida_em</code>, <code>_decidida_por</code>, <code>_justificativa</code>). Ao liberar: justificativa obrigatória, status volta para <code>aguardando_pdv</code> e o OTP ganha pelo menos 10 minutos.</td></tr>\n<tr><td><code>decisao_invalida</code></td><td>Valor diferente de <code>liberado</code> ou <code>recusado</code>.</td></tr>\n<tr><td><code>justificativa_obrigatoria</code></td><td>Liberação sem justificativa.</td></tr>\n<tr><td><code>ja_decidido</code> · <code>nao_pendente</code> · <code>expirado</code></td><td>Já decidido; não é negado por <code>regras_cliente</code>; OTP vencido.</td></tr>\n<tr><td><code>nao_encontrado</code> · <code>nao_autorizado</code></td><td>Id inexistente; usuário não é da empresa do abastecimento.</td></tr></table>\n<p>Contagem para as notificações: <code>contar_abastecimentos_negados_pendentes_pdv(empresa)</code>, recalculada por Realtime e a cada 30 s (o pedido vence sem gerar evento no banco).</p>\n\n<h3 id=\"pdv-prepedido\">2.3 Pré-Pedido</h3>\n<p>O cliente cria um pré-pedido por veículo, com paradas ordenadas por posto (Parâmetros de uso → Pré-Pedido). Cada parada ativa tem um número aleatório de 6 dígitos que o motorista informa no posto.</p>\n<pre class=\"mermaid\">\nflowchart TD\n  A[\"Gestor cria pré-pedido<br/>(placa + paradas por posto)\"] --> B[\"Primeira parada recebe<br/>código de 6 dígitos\"]\n  B --> C[\"Motorista informa o número ao caixa<br/>campo no PDV\"]\n  C --> D[\"consultar_pre_pedido_pdv / informar_pre_pedido_pdv\"]\n  D --> E[\"iniciar_abastecimento_pre_pedido_pdv<br/>(código, leitura, terminal)\"]\n  E --> F{\"limite_pre_pedido_abastecimento_pdv<br/>litros ou valor dentro do limite?\"}\n  F -- \"não\" --> G[\"concluir: negado<br/>pre_pedido_limite\"]\n  F -- \"sim\" --> H[\"concluir: confirmado\"]\n  H --> I[\"parada marcada como atendida<br/>próxima parada recebe novo código\"]\n  I --> J{\"há paradas abertas?\"}\n  J -- \"não\" --> K[\"pré-pedido concluído\"]\n  J -- \"sim\" --> B\n</pre>\n\n<h3 id=\"pdv-resgate\">2.4 Resgate de voucher de fidelidade</h3>\n<p>O motorista troca pontos por um benefício e apresenta o voucher no posto. O caixa valida e queima o voucher; o posto passa a ter um valor a receber (acerto entre a FNI e o posto).</p>\n<pre class=\"mermaid\">\nsequenceDiagram\n  actor Mot as Motorista\n  actor Cx as Caixa\n  participant DB as Supabase\n  Mot->>DB: resgatar_item_catalogo(item, dependente)\n  DB-->>Mot: voucher (número, validade)\n  Mot->>Cx: apresenta o número do voucher\n  Cx->>DB: buscar_voucher_pdv(empresa, código)\n  DB-->>Cx: título, categoria, validade, situação\n  Cx->>DB: queimar_voucher_fidelidade(empresa, código, origem pdv, terminal)\n  DB-->>Cx: queimado (valor a receber registrado)\n  Cx->>DB: listar_resgates_pdv(empresa, de, até)\n</pre>\n\n<h3 id=\"pdv-ajuste\">2.5 Pedido de ajuste de abastecimento</h3>\n<p>Corrige dados de um abastecimento concluído (litros, valor, placa etc.) com aprovação da <b>outra parte</b>: se o posto pede, o cliente decide; se o cliente pede, o posto decide. Um pedido pendente por abastecimento.</p>\n<pre class=\"mermaid\">\nsequenceDiagram\n  actor S as Solicitante (posto ou cliente)\n  participant DB as Supabase\n  participant E as Edge pdv-ajuste-email\n  actor D as Decisor (contraparte)\n  S->>DB: solicitar_ajuste_pdv(id, alterações, motivo, lado)\n  DB->>DB: ajuste_status = pendente (trigger registrar_ajuste_no_abastecimento_pdv)\n  DB->>E: trigger notificar_ajuste_pdv_email\n  E-->>D: e-mail\n  DB-->>D: bolinha no menu, aviso flutuante, banner PWA Cliente\n  Note over S: Extrato mostra \"Em ajuste\"<br/>novo pedido bloqueado\n  alt aprovar\n    D->>DB: decidir_ajuste_pdv(id, true, motivo)\n    DB->>DB: aplica alterações e guarda antes e depois\n  else recusar\n    D->>DB: decidir_ajuste_pdv(id, false, motivo obrigatório)\n    DB->>DB: ajuste_status = recusado, ajuste_motivo, decidido_por, decidido_em\n  else cancelar\n    S->>DB: cancelar_ajuste_pdv(id)\n  end\n  DB-->>S: e-mail com a decisão\n</pre>\n<table>\n<tr><th>Coluna em <code>abastecimentos_pdv</code></th><th>Conteúdo</th></tr>\n<tr><td><code>ajuste_status</code></td><td><code>pendente</code> · <code>aprovado</code> · <code>recusado</code> · <code>cancelado</code></td></tr>\n<tr><td><code>ajuste_motivo</code></td><td>Motivo informado na decisão (obrigatório na recusa, erro <code>motivo_recusa_obrigatorio</code>).</td></tr>\n<tr><td><code>ajuste_lado_solicitante</code></td><td><code>posto</code> ou <code>cliente</code>.</td></tr>\n<tr><td><code>ajuste_decidido_por</code> · <code>ajuste_decidido_em</code> · <code>ajuste_atualizado_em</code></td><td>Quem decidiu e quando.</td></tr>\n</table>\n\n<h3 id=\"pdv-hodometro\">2.6 Hodômetro e antifraude</h3>\n<p>O último hodômetro do veículo é dado sensível de regra de negócio: <b>ninguém vê</b> (motorista, caixa, colaborador, posto). A validação acontece no servidor.</p>\n<pre class=\"mermaid\">\nflowchart LR\n  F[\"Motorista fotografa o hodômetro\"] --> O[\"POST /api/ocr/hodometro<br/>sugere um valor\"]\n  O --> C[\"Motorista confere e corrige\"]\n  C --> I[\"iniciar_abastecimento_pdv(..., p_hodometro)\"]\n  I --> V{\"ultimo_hodometro_veiculo_interno<br/>novo valor maior que o último?\"}\n  V -- \"não\" --> E[\"erro sem revelar o valor anterior\"]\n  V -- \"sim\" --> G[\"grava no abastecimento\"]\n  G --> R[\"PDV: Resumo da venda mostra só o hodômetro<br/>já validado deste abastecimento\"]\n</pre>\n<p><code>ultimo_hodometro_veiculo(placa)</code> continua existindo e devolve <code>null</code> (compatibilidade com PWAs antigos em cache). A função <code>ultimo_hodometro_veiculo_interno</code> não tem permissão para <code>anon</code> nem <code>authenticated</code>.</p>\n\n<h3 id=\"pdv-extrato\">2.7 Perfis no PDV</h3>\n<p><b>Posto</b> (gestor): todas as telas, mais Minha Equipe e Permissões no painel web. <b>Colaborador</b> e <b>Caixa</b>: o que o gestor liberar. O padrão do Caixa é só as telas do PDV. Quem convida define o perfil: Colaborador ou Caixa para postos, Analista para clientes.</p>\n\n<h2 id=\"web\">3. Painel web Gestão de Frotas</h2>\n<p>Aplicação Next.js com cerca de 150 telas em <code>src/app/(dashboard)</code>. O menu muda por visão (admin, cliente/frota, posto) e por permissão. Abaixo, os fluxos principais.</p>\n\n<h3 id=\"web-acesso\">3.1 Acesso, perfis e permissões</h3>\n<pre class=\"mermaid\">\nflowchart TD\n  L[\"Login (Supabase Auth)\"] --> P[\"perfil_usuario_atual()\"]\n  P --> V{\"visão\"}\n  V -- \"admin\" --> VA[\"Todos os clientes e postos<br/>escolhe o cliente atual no menu\"]\n  V -- \"gestor_frota ou analista\" --> VF[\"Visão cliente<br/>empresas_do_usuario(email)\"]\n  V -- \"posto, colaborador, caixa\" --> VP[\"Visão posto<br/>Meu Posto, PDV, financeiro do posto\"]\n  VA --> M[\"Menu = catálogo de funcionalidades<br/>filtrado por permissoes_perfil\"]\n  VF --> M\n  VP --> M\n  M --> R[\"Rota bloqueada se funcionalidade negada\"]\n</pre>\n<h4>Quem decide o quê em Permissões</h4>\n<table>\n<tr><th>Quem abre</th><th>Perfis que aparecem na matriz</th><th>Escopo</th></tr>\n<tr><td>admin</td><td>admin, gestor_frota, posto</td><td>Padrão global (empresa sentinela).</td></tr>\n<tr><td>gestor_frota</td><td>analista</td><td>Só da própria empresa.</td></tr>\n<tr><td>posto</td><td>colaborador, caixa</td><td>Só da própria empresa.</td></tr>\n</table>\n<h4>Convite de usuários (Minha Equipe)</h4>\n<pre class=\"mermaid\">\nflowchart LR\n  G[\"Gestor do cliente\"] -->|\"convida\"| A[\"entra como Analista\"]\n  H[\"Gestor do posto\"] -->|\"convida e escolhe\"| B[\"Colaborador<br/>ou Caixa\"]\n  X[\"Admin FNI\"] -->|\"/usuarios, importação, convite global\"| C[\"qualquer perfil, qualquer empresa\"]\n  G -->|\"deixar de ser gestor\"| D[\"rebaixa para o perfil de entrada do segmento\"]\n</pre>\n<p>A rota <code>POST /api/usuarios/convidar</code> e as telas <code>/usuarios</code> são exclusivas do admin. O analista não gerencia usuários.</p>\n\n<h3 id=\"web-abast\">3.2 Abastecimentos e importações</h3>\n<p>Todos os canais de entrada gravam em tabelas específicas e são unificados na visão <code>/abastecimentos</code>. Todo abastecimento precisa ter motorista (CPF e nome); sem motorista cai em <code>/abastecimentos-sem-motorista</code>.</p>\n<pre class=\"mermaid\">\nflowchart LR\n  subgraph Entradas\n    PDV[\"PDV FNI<br/>abastecimentos_pdv\"]\n    PF[\"PróFrotas<br/>sync horário\"]\n    EXT[\"Cartões de combustível<br/>POST /api/integracoes/abastecimentos\"]\n    FOR[\"ERP do posto<br/>POST .../abastecimentos-fornecidos\"]\n    PL[\"Planilha<br/>/abastecimentos/importar\"]\n    MAN[\"Lançamento manual<br/>+ OCR do cupom\"]\n    INT[\"Interno<br/>(posto próprio da frota)\"]\n  end\n  PDV --> U[(\"Visão unificada<br/>de abastecimentos\")]\n  PF --> U\n  EXT --> U\n  FOR --> U\n  PL --> U\n  MAN --> U\n  INT --> U\n  U --> SM{\"tem motorista?\"}\n  SM -- \"não\" --> RES[\"/abastecimentos-sem-motorista<br/>resolver ou vincular\"]\n  SM -- \"sim\" --> IND[\"Indicadores, financeiro,<br/>fidelidade, antifraude, NF\"]\n  RES --> IND\n</pre>\n<ul>\n<li><b>Aprovação:</b> abastecimentos que exigem aprovação aparecem em <code>/abastecimentos/pendentes-aprovacao</code>.</li>\n<li><b>Ajuste de abastecimento PDV:</b> detalhe em <code>/abastecimentos/pdv/[id]</code> mostra o bloco do último pedido de ajuste (status, quem, quando, motivo).</li>\n<li><b>Rotina de auto-confirmação:</b> <code>/api/cron/auto-confirmar-fidelidade</code> diária às 06:00.</li>\n</ul>\n\n<h3 id=\"web-parametros\">3.3 Parâmetros de uso e antifraude</h3>\n<p>Em <code>/parametros-uso</code> o cliente cadastra as regras que limitam o abastecimento. As mesmas regras alimentam o PDV (<code>avaliar_regras_abastecimento_pdv</code>) e a consulta externa (<code>/api/integracoes/parametros/*</code>). Cada aba tem filtros por placa, motorista e status.</p>\n<table>\n<tr><th>Tipo de regra</th><th>Exemplo</th></tr>\n<tr><td>Vínculo motorista ↔ veículo</td><td>Só o par ativo pode abastecer.</td></tr>\n<tr><td>Intervalo, dias e horários</td><td>Mínimo de horas entre abastecimentos; janela do dia.</td></tr>\n<tr><td>Valor diário, volume diário, cotas</td><td>Teto por dia ou por período.</td></tr>\n<tr><td>Produto e serviços</td><td>Quais combustíveis e serviços são permitidos.</td></tr>\n<tr><td>Postos permitidos</td><td>Lista da rede autorizada.</td></tr>\n<tr><td>Hodômetro (leve e pesado)</td><td>Variação máxima entre abastecimentos.</td></tr>\n<tr><td>Parâmetros de NF</td><td>Exigências fiscais por UF e CNPJ da frota.</td></tr>\n<tr><td>Pré-Pedido</td><td>Rota de paradas por veículo, com limites.</td></tr>\n</table>\n<p>Também há regras de antifraude (<code>/antifraude</code>): <code>limite_valor_quantidade</code> e <code>janela_tempo_frequencia</code>, por escopo motorista, veículo ou empresa. O endpoint <code>POST /api/integracoes/antifraude/verificar</code> responde <code>{ autorizado: true }</code> ou a lista de violações.</p>\n<pre class=\"mermaid\">\nflowchart TD\n  S[\"Sistema externo ou PDV<br/>(placa, CPF, posto, data, litros, valor)\"] --> R[\"Carrega regras ativas da empresa<br/>por motorista, veículo e empresa\"]\n  R --> E{\"viola alguma regra?\"}\n  E -- \"não\" --> OK[\"autorizado: true\"]\n  E -- \"sim, corrigível\" --> C[\"PDV: pede ajuste e tenta de novo\"]\n  E -- \"sim, não corrigível\" --> N[\"negado → aguarda liberação do gestor\"]\n</pre>\n\n<h3 id=\"web-neg\">3.4 Negociação com postos revendedores</h3>\n<p>O cliente propõe preço e volume mínimo mensal por combustível; o posto aceita, recusa ou contrapropõe, em rodadas. Pode ser feito pela tela ou, no lado do posto, pela API (<code>/api/integracoes/negociacoes</code>).</p>\n<pre class=\"mermaid\">\nstateDiagram-v2\n  [*] --> proposta: cliente cria (CNPJ do cliente, combustível, vigência, volume, preço)\n  proposta --> contraproposta: posto envia nova rodada\n  contraproposta --> contraproposta: nova rodada\n  proposta --> aceita: posto ou cliente aceita\n  contraproposta --> aceita\n  proposta --> recusada\n  contraproposta --> recusada\n  aceita --> [*]\n  recusada --> [*]\n</pre>\n<p>Cada rodada envia e-mail pela Edge Function <code>negociacao-email</code>. A aderência do cliente à rede negociada é medida em <code>aderencia_rede_negociada(empresa, dias)</code> e aparece em <code>/negociacoes</code>.</p>\n\n<h3 id=\"web-fid\">3.5 Fidelidade e resgates</h3>\n<pre class=\"mermaid\">\nflowchart LR\n  A[\"Abastecimento confirmado<br/>(PDV, PróFrotas etc.)\"] --> P[\"Pontos creditados no CPF<br/>do motorista\"]\n  P --> C[\"Catálogo de benefícios<br/>(/fidelidade)\"]\n  C --> R[\"resgatar_item_catalogo → voucher\"]\n  R --> Q[\"Posto queima no PDV<br/>queimar_voucher_fidelidade\"]\n  Q --> F[\"Valor a receber do posto<br/>/fidelidade/resgates\"]\n</pre>\n<p>Indicadores em <code>/fidelidade-motoristas</code>: taxa de resgate e pontos parados. Em <code>/assinaturas</code>: trials mortos, inatividade, health score por empresa.</p>\n\n<h3 id=\"web-nf\">3.6 Notas fiscais</h3>\n<p>O ERP do posto envia o XML da NF-e (modelo 55) pelo endpoint <code>POST /api/integracoes/notas-fiscais</code>, ou o usuário envia em <code>/notas-fiscais</code>. O sistema lê o XML, cruza com o abastecimento e marca a conclusão de NF visível para cliente e posto.</p>\n<pre class=\"mermaid\">\nsequenceDiagram\n  participant ERP as ERP do posto\n  participant API as /api/integracoes/notas-fiscais\n  participant DB as Supabase\n  ERP->>API: POST XML bruto (Bearer chave, escopo notas_fiscais:write)\n  API->>API: extrai chave de acesso, produto, valores\n  API->>DB: RPC de matching com abastecimento\n  API->>DB: guarda XML no storage notas-fiscais-xml\n  DB-->>API: vinculada, pendente ou divergente\n  API-->>ERP: resultado\n</pre>\n\n<h3 id=\"web-fin\">3.7 Financeiro e conciliação</h3>\n<ul>\n<li><b>Faturas de postos:</b> robô diário às 03:00 (<code>gerar_faturas_postos_robo</code>). <b>Faturas de fretes:</b> mensal, dia 1 às 03:30.</li>\n<li><b>Conciliação bancária:</b> automática diária às 07:00 (<code>/api/cron/conciliacao-automatica</code>), com tela de apoio em <code>/conciliacao-bancaria</code>.</li>\n<li><b>Meios de pagamento externos:</b> faturas de provedores entram por <code>POST /api/integracoes/faturas-meio-pagamento</code> (fatura + abastecimentos).</li>\n<li><b>Custos fixos</b> (seguro, IPVA, licenciamento, rastreamento, multas): <code>POST /api/integracoes/custos-fixos</code>.</li>\n</ul>\n\n<h3 id=\"web-rede\">3.8 Inteligência de rede e ANP</h3>\n<pre class=\"mermaid\">\nflowchart LR\n  ANP[\"ANP (preços e cadastro)\"] --> EP[\"Edge atualizar-precos-anp<br/>seg 09:00 + terça 12:00 (rede de segurança)\"]\n  ANP --> EO[\"Edge atualizar-postos-anp<br/>terça 13:00 UTC, grava anp_postos.atualizado_em\"]\n  EP --> T[(\"tabelas de preços\")]\n  EO --> T2[(\"anp_postos ~46 mil postos\")]\n  T --> CP[\"atualizar_cache_precos_postos<br/>a cada 6 h\"]\n  CP --> UI[\"Mapa de preços, conferência de preços,<br/>combustível ideal, inteligência de rede\"]\n  T2 --> UI\n</pre>\n<div class=\"note\">Horários do pg_cron estão em UTC. <code>0 13 * * 2</code> equivale a 10:00 no horário de Brasília. Importações manuais continuam disponíveis: <code>/api/postos/importar-anp</code>, <code>/api/postos/importar-precos</code> e <code>/api/inteligencia-rede/importar-precos-anp</code>.</div>\n\n<h3 id=\"web-assin\">3.9 Assinaturas e cobrança</h3>\n<pre class=\"mermaid\">\nsequenceDiagram\n  actor U as Usuário\n  participant W as Painel web\n  participant E as Edge create-checkout-session\n  participant S as Stripe\n  participant H as Edge stripe-webhook\n  participant DB as Supabase\n  U->>W: escolhe plano (planos-precos)\n  W->>E: criar sessão de checkout\n  E->>S: cria Checkout Session\n  S-->>U: página de pagamento\n  S->>H: evento (pagamento, renovação, cancelamento)\n  H->>DB: grava stripe_events e atualiza assinatura\n  U->>W: gerenciar cobrança\n  W->>S: create-billing-portal-session\n</pre>\n<p>Rotinas relacionadas: <code>email-trials</code> (diário 09:00) e <code>reportar-excedente-veiculos / postos / empresas-grupo</code> (04:30, 04:35 e 04:40) para cobrança por uso acima do plano.</p>\n\n<h3 id=\"web-outros\">3.10 Demais módulos (resumo)</h3>\n<table>\n<tr><th>Módulo</th><th>Rotas principais</th><th>O que faz</th></tr>\n<tr><td>Frota</td><td><code>/veiculos</code> <code>/motoristas</code> <code>/pneus</code> <code>/checklist-veiculos</code> <code>/manutencao-preditiva</code> <code>/oficinas</code></td><td>Cadastros, manutenção, pneus, checklists, alertas de vencimento (CNH, ASO, apólice).</td></tr>\n<tr><td>Ocorrências</td><td><code>/multas</code> <code>/sinistros</code> <code>/apolices-seguro</code></td><td>Multas (com auto-indicação do condutor quando há candidato único), sinistros e apólices.</td></tr>\n<tr><td>Fretes</td><td><code>/fretes</code> <code>/bolsa-fretes</code> <code>/tabelas-frete</code> <code>/faturas-fretes</code> <code>/planos-viagem</code> <code>/rotograma</code></td><td>Contratação, negociação, faturamento, CT-e/MDF-e (webhook fiscal), SLA e botão de pânico.</td></tr>\n<tr><td>Roteirização</td><td><code>/roteirizacao/*</code> <code>/programacao</code> <code>/combustivel-ideal</code></td><td>Rotas, paradas, plano de abastecimento.</td></tr>\n<tr><td>Inteligência</td><td><code>/indicadores-frota</code> <code>/insights-ia</code> <code>/acoes-sugeridas</code> <code>/anomalias</code> <code>/tco</code> <code>/pegada-carbono</code> <code>/assistente</code></td><td>Indicadores, insights diários por IA (05:00), ações sugeridas (09:00), assistente conversacional.</td></tr>\n<tr><td>Posto</td><td><code>/meu-posto</code> <code>/clientes-posto</code> <code>/financeiro-posto</code> <code>/relatorios-posto</code> <code>/inteligencia-comercial-posto</code> <code>/pdv-bicos</code> <code>/pdv-formas-pagamento</code> <code>/pdv-metricas</code></td><td>Visão do posto: clientes, financeiro, relatórios, configuração do PDV.</td></tr>\n<tr><td>Administração</td><td><code>/assinaturas</code> <code>/central-avisos</code> <code>/central-conteudo</code> <code>/crm-comercial</code> <code>/log-auditoria</code> <code>/lgpd</code> <code>/integracoes</code> <code>/usuarios</code></td><td>Planos, comunicação, CRM, auditoria, LGPD e geração de chaves de API.</td></tr>\n</table>\n\n<h2 id=\"mot\">4. PWA Motorista</h2>\n<p>Projeto Flutter <code>estrada-que-cuida</code>. Módulos principais: <code>abastecimento_pdv</code>, <code>abastecimento_manual</code>, <code>abastecimento_interno</code>, <code>extrato</code> (pontos), <code>catalogo</code> (resgates), <code>gamificacao</code>, <code>inspecao_veicular</code>, <code>jornada</code>, <code>fretes</code>, <code>roteirizacao</code>, <code>chamados</code>, <code>vinculo</code>, <code>avaliacao</code>, <code>dependentes</code>.</p>\n<pre class=\"mermaid\">\nflowchart TD\n  H[\"Home do motorista\"] --> A[\"Abastecer neste posto<br/>geolocalização bloqueante\"]\n  A --> RV[\"Escolhe revenda próxima<br/>buscar_revendas_pdv_proximas\"]\n  RV --> PL[\"Informa placa\"]\n  PL --> HO[\"Foto do hodômetro<br/>OCR + quadro de enquadramento\"]\n  HO --> CO[\"Código + OTP com contador<br/>acompanhamento em tempo real\"]\n  CO --> ST{\"resultado\"}\n  ST -- \"confirmado\" --> AV[\"Avaliação do abastecimento<br/>pontos creditados\"]\n  ST -- \"negado\" --> WT[\"Aguarda liberação do gestor<br/>(Realtime)\"]\n  WT --> ST\n  H --> CAT[\"Catálogo: resgatar benefício → voucher\"]\n  H --> EXT[\"Extrato de pontos com filtros\"]\n  H --> MAN[\"Abastecimento externo<br/>OCR do cupom\"]\n</pre>\n<ul>\n<li>O motorista <b>não vê</b> o último hodômetro do veículo. O campo é preenchido por ele (ou pela leitura OCR) e validado só no servidor.</li>\n<li>O card de consumo (km/l) diferencia \"sem dado\" de \"descartado por segurança\" e funciona com um motorista em vários veículos.</li>\n<li>O tema (claro, escuro ou sistema) fica vinculado à conta (<code>tema_preferido</code>).</li>\n<li>O motorista abastece em vários postos, então o hodômetro não é compartilhado entre telas.</li>\n</ul>\n\n<h2 id=\"cli\">5. PWA Cliente</h2>\n<p>Projeto Flutter <code>estudo-de-rede/flutter</code>, para gestor e equipe do cliente no celular. Destaques de fluxo: <b>Abastecimentos negados</b> (lista, liberar ou recusar, bolinha no menu, banner vermelho na Home) e o <b>banner de pedidos de ajuste</b> (âmbar, abre o painel web na tela de decisão).</p>\n<pre class=\"mermaid\">\nflowchart LR\n  RT[\"Realtime em abastecimentos_pdv e pdv_ajustes\"] --> P[\"Providers Riverpod<br/>negadosPdvPendentesProvider<br/>ajustesPdvPendentesProvider\"]\n  P --> B1[\"BannerNegadosPdv (vermelho)\"]\n  P --> B2[\"BannerAjustesPdv (âmbar)\"]\n  B1 --> T[\"/abastecimentos-negados<br/>decidir_abastecimento_negado_pdv\"]\n  B2 --> W[\"abre o painel web<br/>/ajustes-pdv\"]\n</pre>\n<div class=\"note warn\">Hoje a decisão do pedido de ajuste ainda é feita no painel web. O PWA Cliente apenas avisa e abre o painel.</div>\n\n<h2 id=\"api-conv\">6. Convenções e autenticação</h2>\n<p>Existem cinco mecanismos de autenticação, conforme quem chama:</p>\n<table>\n<tr><th>Mecanismo</th><th>Quem usa</th><th>Como</th><th>Rotas</th></tr>\n<tr><td>Sessão Supabase (JWT)</td><td>Painel, PDV, PWAs</td><td>Cookie (web) ou <code>Authorization: Bearer &lt;access_token&gt;</code> (PWAs nas rotas OCR e assistente). RLS e RPCs usam o e-mail do JWT.</td><td>RPCs, <code>/api/ocr/*</code>, <code>/api/assistente</code>, <code>/api/usuarios/convidar</code></td></tr>\n<tr><td>Chave de API com escopo</td><td>ERPs, cartões, GPS, postos</td><td><code>Authorization: Bearer fni_cf_…</code>. Só o hash SHA-256 fica no banco (<code>api_keys.hash_chave</code>); a chave aparece uma única vez na geração. Cada endpoint exige um escopo.</td><td><code>/api/integracoes/*</code>, <code>/api/cadastros/*</code></td></tr>\n<tr><td><code>CRON_SECRET</code></td><td>pg_cron / agendadores</td><td><code>Authorization: Bearer &lt;CRON_SECRET&gt;</code></td><td><code>/api/cron/*</code></td></tr>\n<tr><td>Segredo de webhook</td><td>Provedores fiscal e de cobrança</td><td>Header <code>x-webhook-secret</code> (<code>FISCAL_WEBHOOK_SECRET</code>, <code>COBRANCA_WEBHOOK_SECRET</code>). O evento bruto é gravado antes do processamento.</td><td><code>/api/webhooks/*</code></td></tr>\n<tr><td>Segredo na URL</td><td>UptimeRobot</td><td>Segredo como parâmetro da URL (o serviço não aceita headers customizados).</td><td><code>/api/alertas/uptimerobot</code></td></tr>\n</table>\n<h4>Convenções gerais</h4>\n<ul>\n<li><b>Formato:</b> JSON, datas em ISO 8601, valores em número (ponto decimal). A exceção é <code>notas-fiscais</code>, que recebe o XML bruto.</li>\n<li><b>Erros:</b> <code>{ \"erro\": \"mensagem\" }</code> com <code>400</code> (corpo inválido), <code>401</code> (chave ausente, inválida ou revogada), <code>403</code> (falta escopo; a mensagem lista os escopos da chave), <code>404</code>, <code>500</code>.</li>\n<li><b>Idempotência:</b> endpoints de abastecimento aceitam <code>transacao_externa_id</code>; repetir devolve <code>200 { \"status\": \"ja_existia\" }</code> em vez de duplicar.</li>\n<li><b>Paginação (GET):</b> <code>limit</code> (padrão 100, máximo 500) e <code>offset</code>. Resposta: <code>{ total, limit, offset, dados: [...] }</code>.</li>\n<li><b>Isolamento:</b> a empresa vem sempre da chave, nunca do corpo. Um posto não consegue lançar venda em nome de outro (CNPJ e nome do posto são os da empresa dona da chave).</li>\n<li><b>Último uso:</b> cada chamada com sucesso atualiza <code>api_keys.ultimo_uso</code>.</li>\n</ul>\n<pre class=\"mermaid\">\nsequenceDiagram\n  participant S as Sistema externo\n  participant R as Route Handler Next.js\n  participant DB as Supabase (service role)\n  S->>R: POST /api/integracoes/... Authorization: Bearer chave\n  R->>R: SHA-256 da chave\n  R->>DB: api_keys onde hash_chave = hash\n  alt chave inexistente, inativa ou revogada\n    R-->>S: 401\n  else escopo ausente\n    R-->>S: 403\n  else ok\n    R->>DB: grava ou consulta dados da empresa da chave\n    R->>DB: atualiza ultimo_uso\n    R-->>S: 200 ou 201 com JSON\n  end\n</pre>\n\n<h2 id=\"api-ext\">7. API externa (chave de API)</h2>\n<p>Base: o domínio do painel web (<code>https://fxgestaodefrotasonline.com</code>). As chaves são geradas no painel, em <code>/integracoes</code>, por quem é dono do recurso: <b>cliente</b> (frota) para escritas de abastecimento, manutenção, custos, GPS; <b>posto</b> para negociações, notas fiscais e abastecimentos fornecidos.</p>\n<h3 id=\"api-ext-lista\">7.1 Catálogo de endpoints</h3>\n<table>\n<tr><th>Método e rota</th><th>Escopo</th><th>Quem gera a chave</th><th>Função</th></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/abastecimentos</code></td><td><code>abastecimentos:write</code></td><td>Cliente</td><td>Provedor de cartão lança transação de abastecimento.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/abastecimentos-fornecidos</code></td><td><code>abastecimentos_fornecidos:write</code></td><td>Posto</td><td>Sistema de automação do posto lança abastecimento realizado (cliente identificado por CNPJ).</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/faturas-meio-pagamento</code></td><td><code>faturas_meio_pagamento:write</code></td><td>Cliente</td><td>Fatura de meio de pagamento com seus abastecimentos.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/custos-fixos</code></td><td><code>custos_fixos:write</code></td><td>Cliente</td><td>Seguro, IPVA, licenciamento, rastreamento, multas.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/manutencoes</code></td><td><code>manutencoes:write</code></td><td>Cliente</td><td>Manutenção realizada.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/gps</code></td><td><code>gps:write</code></td><td>Cliente</td><td>Posições GPS (uma ou lote).</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/notas-fiscais</code></td><td><code>notas_fiscais:write</code></td><td>Posto</td><td>XML de NF-e vinculada a abastecimento.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/antifraude/verificar</code></td><td><code>antifraude:verificar</code></td><td>Cliente</td><td>Consulta prévia: autoriza ou nega um abastecimento.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><span class=\"badge post\">POST</span><code>/api/integracoes/negociacoes</code></td><td><code>negociacoes:read</code> (GET) · <code>negociacoes:write</code> (POST)</td><td>Posto</td><td>Lista e cria propostas.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/negociacoes/{id}/rodadas</code></td><td><code>negociacoes:write</code></td><td>Posto</td><td>Contraproposta.</td></tr>\n<tr><td><span class=\"badge post\">POST</span><code>/api/integracoes/negociacoes/{id}/decisao</code></td><td><code>negociacoes:write</code></td><td>Posto</td><td>Aceitar ou recusar.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/integracoes/parametros/vinculo</code></td><td><code>parametros_vinculo:read</code></td><td>Cliente</td><td>Vínculo motorista ↔ veículo (filtros <code>placa</code>, <code>cpf</code>).</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/integracoes/parametros/{intervalo | valor-diario | volume-diario | produto | hodometro | dias-horarios | postos | servicos | cotas}</code></td><td><code>parametros_&lt;tipo&gt;:read</code></td><td>Cliente</td><td>Regras de uso cadastradas, uma rota por tipo.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/integracoes/parametros-nf</code></td><td><code>parametros_nf:read</code></td><td>Cliente</td><td>Parâmetros fiscais (filtros <code>cnpj_frota</code>, <code>uf</code>).</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/cadastros/veiculos</code></td><td><code>veiculos:read</code></td><td>Cliente</td><td>Cadastro de veículos.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/cadastros/motoristas</code></td><td><code>motoristas:read</code></td><td>Cliente</td><td>Cadastro de motoristas.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/cadastros/centros-custo</code></td><td><code>centros_custo:read</code></td><td>Cliente</td><td>Centros de custo.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/cadastros/postos</code></td><td><code>postos:read</code></td><td>Cliente</td><td>Postos.</td></tr>\n<tr><td><span class=\"badge get\">GET</span><code>/api/cadastros/usuarios</code></td><td><code>usuarios:read</code></td><td>Cliente</td><td>Usuários da empresa.</td></tr>\n</table>\n\n<h3 id=\"api-ext-detalhe\">7.2 Detalhe dos principais</h3>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/abastecimentos</code> — escopo <code>abastecimentos:write</code></div><div class=\"bd\">\n<p>Provedor de cartão (Ticket Log, Alelo, Repom…) envia cada transação. Grava em <code>abastecimentos_externos</code>, que entra nos indicadores financeiros. Placa e motorista são cadastrados automaticamente se não existirem.</p>\n<table><tr><th>Campo</th><th>Tipo</th><th>Obrigatório</th></tr>\n<tr><td><code>provedor</code></td><td>texto (ex.: <code>ticket_log</code>)</td><td>sim</td></tr>\n<tr><td><code>placa</code></td><td>texto</td><td>sim</td></tr>\n<tr><td><code>data_abastecimento</code></td><td>ISO 8601</td><td>sim</td></tr>\n<tr><td><code>quantidade</code> (litros)</td><td>número ≥ 0</td><td>sim</td></tr>\n<tr><td><code>valor_total</code></td><td>número ≥ 0</td><td>sim</td></tr>\n<tr><td><code>motorista_nome</code>, <code>motorista_cpf</code>, <code>hodometro</code>, <code>posto_nome</code>, <code>posto_cnpj</code>, <code>combustivel</code>, <code>valor_unitario</code>, <code>transacao_externa_id</code></td><td>vários</td><td>opcionais (CPF e nome do motorista são fortemente recomendados)</td></tr></table>\n<pre>curl -X POST https://fxgestaodefrotasonline.com/api/integracoes/abastecimentos \\\n  -H \"Authorization: Bearer fni_cf_...\" -H \"Content-Type: application/json\" \\\n  -d '{\"provedor\":\"ticket_log\",\"placa\":\"ABC1D23\",\"motorista_cpf\":\"12345678900\",\n       \"data_abastecimento\":\"2026-10-05T14:30:00Z\",\"combustivel\":\"Diesel S10\",\n       \"quantidade\":120.5,\"valor_unitario\":6.12,\"valor_total\":737.46,\n       \"transacao_externa_id\":\"TL-998877\"}'</pre>\n<p><b>Resposta:</b> <code>201 { \"id\": ..., \"status\": \"criado\" }</code> · repetição: <code>200 { \"status\": \"ja_existia\" }</code>.</p></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/abastecimentos-fornecidos</code> — escopo <code>abastecimentos_fornecidos:write</code></div><div class=\"bd\">\n<p>Chave gerada pelo <b>posto</b>. O cliente (frota) vem no corpo por CNPJ; CNPJ e nome do posto são sempre os da empresa dona da chave.</p>\n<table><tr><th>Campo</th><th>Observação</th></tr>\n<tr><td><code>cliente_cnpj</code></td><td>obrigatório; resolvido para <code>empresa_id</code></td></tr>\n<tr><td><code>sistema</code></td><td>nome do sistema de automação (ex.: Tanknomia, SAT)</td></tr>\n<tr><td><code>placa</code>, <code>data_abastecimento</code>, <code>quantidade</code>, <code>valor_total</code></td><td>obrigatórios</td></tr>\n<tr><td><code>motorista_nome</code>, <code>motorista_cpf</code>, <code>hodometro</code>, <code>combustivel</code>, <code>valor_unitario</code>, <code>transacao_externa_id</code></td><td>opcionais</td></tr></table>\n<p><b>Resposta:</b> <code>201 { \"id\", \"status\": \"criado\" }</code> ou <code>200 { \"status\": \"ja_existia\" }</code>.</p></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/antifraude/verificar</code> — escopo <code>antifraude:verificar</code></div><div class=\"bd\">\n<p>O sistema do cliente consulta antes de liberar o abastecimento. Aplica bloqueios e regras (<code>limite_valor_quantidade</code>, <code>janela_tempo_frequencia</code>) por motorista, veículo e empresa. Se o posto consta como parada pendente de um pré-pedido da placa, a parada é marcada como atendida.</p>\n<table><tr><th>Campo</th><th>Observação</th></tr>\n<tr><td><code>placa</code>, <code>motorista_cpf</code>, <code>posto_cnpj</code></td><td>identificam a operação</td></tr>\n<tr><td><code>data_hora</code></td><td>ISO 8601 (400 se inválida)</td></tr>\n<tr><td><code>litros</code>, <code>valor_total</code></td><td>comparados com os limites</td></tr></table>\n<p><b>Resposta:</b> <code>{ \"autorizado\": true }</code> ou <code>{ \"autorizado\": false, \"motivo\": \"...\", ... }</code>. <b>Falha nossa é fail-open:</b> devolve <code>autorizado: true</code>, grava em <code>antifraude_verificacoes_falhas</code> e avisa por e-mail (<code>antifraude-email</code>), para nunca travar a operação do cliente.</p></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/notas-fiscais</code> — escopo <code>notas_fiscais:write</code></div><div class=\"bd\">\n<p>Corpo = <b>XML bruto</b> da NF-e autorizada (não JSON). Query opcional: <code>abastecimento_id</code> (força o vínculo) e <code>provedor</code>. Sem <code>abastecimento_id</code>, o sistema procura candidatos por CNPJ emitente/destinatário, data, quantidade e valor.</p>\n<p><b>Resposta:</b> <code>201 { \"status\": \"vinculada\", \"nota_id\", \"abastecimento_id\", \"provedor\", \"aviso\" }</code>. O XML é guardado no bucket <code>notas-fiscais-xml</code>.</p></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/gps</code> — escopo <code>gps:write</code></div><div class=\"bd\">\n<p>Aceita uma posição ou um array. Cada item: <code>placa</code>, <code>lat</code>, <code>lon</code>, <code>timestamp_gps</code> (obrigatórios), <code>velocidade_kmh</code> e <code>provedor</code> (opcionais).</p>\n<p><b>Resposta:</b> <code>201 { \"status\": \"criado\", \"posicoes_recebidas\", \"posicoes_gravadas\", \"itens_invalidos\": [...] }</code>.</p></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><code>/api/integracoes/faturas-meio-pagamento</code> · <code>custos-fixos</code> · <code>manutencoes</code></div><div class=\"bd\">\n<table><tr><th>Rota</th><th>Corpo</th></tr>\n<tr><td>faturas-meio-pagamento</td><td><code>provedor</code>, <code>numero_fatura_externa</code>, <code>periodo_inicio</code>, <code>periodo_fim</code>, <code>vencimento</code>, <code>valor_total</code>, <code>observacoes</code>, <code>abastecimentos[]</code> (mesmos campos de um abastecimento, com <code>transacao_externa_id</code>). Repetir a mesma fatura devolve <code>ja_existia</code>.</td></tr>\n<tr><td>custos-fixos</td><td><code>tipo</code>, <code>valor</code>, <code>competencia</code>, <code>descricao</code>, <code>placa</code>, <code>recorrente</code>. Resposta <code>201 { id, status }</code>.</td></tr>\n<tr><td>manutencoes</td><td><code>placa</code>, <code>data_manutencao</code>, <code>hodometro</code>, <code>tecnico</code>, <code>oficina</code>, <code>custo_total</code>, <code>itens_realizados[]</code>, <code>obs_gerais</code>. Resposta <code>201 { id, status }</code>.</td></tr></table></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge post\">POST</span><span class=\"badge get\">GET</span><code>/api/integracoes/negociacoes</code> e subrotas</div><div class=\"bd\">\n<table><tr><th>Chamada</th><th>Corpo ou resposta</th></tr>\n<tr><td><code>POST /negociacoes</code></td><td><code>cliente_cnpj</code>, <code>combustivel</code>, <code>vigencia_inicio</code>, <code>vigencia_fim</code>, <code>volume_minimo_mensal</code>, <code>preco_unitario</code> → <code>201 { id, status: \"criado\" }</code></td></tr>\n<tr><td><code>GET /negociacoes</code></td><td><code>{ total, limit, offset, dados }</code> das negociações do posto</td></tr>\n<tr><td><code>POST /negociacoes/{id}/rodadas</code></td><td>mesmos campos de preço e vigência → <code>201 { status: \"contraproposta_enviada\" }</code></td></tr>\n<tr><td><code>POST /negociacoes/{id}/decisao</code></td><td><code>{ \"decisao\": \"aceita\" | \"recusada\" }</code> → <code>{ status: \"negociacao_aceita\" | \"negociacao_recusada\" }</code>. <code>404</code> se a negociação não é do posto da chave.</td></tr></table></div></div>\n\n<div class=\"ep\"><div class=\"hd\"><span class=\"badge get\">GET</span><code>/api/integracoes/parametros/*</code> · <code>/api/cadastros/*</code></div><div class=\"bd\">\n<p>Leitura paginada (<code>limit</code>, <code>offset</code>) das regras e cadastros da empresa da chave. Resposta: <code>{ \"total\", \"limit\", \"offset\", \"dados\": [...] }</code>. Exemplo de uso: o sistema do posto consulta <code>/parametros/vinculo?placa=ABC1D23&amp;cpf=12345678900</code> antes de liberar a bomba.</p></div></div>\n\n<h2 id=\"api-int\">8. Rotas internas do painel</h2>\n<table>\n<tr><th>Rota</th><th>Método</th><th>Autenticação</th><th>Função</th></tr>\n<tr><td><code>/api/health</code></td><td>GET</td><td>nenhuma</td><td>Health check usado pelo Railway para decidir o deploy (rollback automático se falhar).</td></tr>\n<tr><td><code>/api/log-cliente</code></td><td>POST</td><td>nenhuma</td><td>Recebe erros de renderização do navegador e grava no log do servidor com o mesmo Request ID.</td></tr>\n<tr><td><code>/api/alertas/uptimerobot</code></td><td>POST</td><td>segredo na URL</td><td>Ponte UptimeRobot → canal do Teams.</td></tr>\n<tr><td><code>/api/assistente</code></td><td>POST</td><td>Bearer (sessão)</td><td>Assistente FNI para o PWA (usa a API da Anthropic; chave secreta fica só no servidor).</td></tr>\n<tr><td><code>/api/ocr/hodometro</code></td><td>POST multipart</td><td>Bearer (sessão)</td><td>Foto do hodômetro (campo <code>arquivo</code>, recorte opcional <code>recorte_x/y/w/h</code>) → valor sugerido. Rate limit por usuário.</td></tr>\n<tr><td><code>/api/ocr/cupom-abastecimento</code></td><td>POST multipart</td><td>Bearer (sessão)</td><td>Cupom de abastecimento externo (máx. 8 MB).</td></tr>\n<tr><td><code>/api/ocr/documento</code></td><td>POST multipart</td><td>Bearer (sessão)</td><td>CT-e e canhoto (máx. 8 MB).</td></tr>\n<tr><td><code>/api/usuarios/convidar</code></td><td>POST</td><td>Bearer (sessão, admin)</td><td>Convite de usuário.</td></tr>\n<tr><td><code>/api/postos/importar</code> · <code>importar-anp</code> · <code>importar-precos</code></td><td>POST multipart</td><td>sessão</td><td>Importação de planilhas de postos, universo ANP (~35 mil linhas) e preços. Route Handler (e não Server Action) para escapar da regra de WAF da Cloudflare.</td></tr>\n<tr><td><code>/api/inteligencia-rede/importar-precos-anp</code></td><td>POST multipart</td><td>sessão</td><td>Importação de preços ANP para inteligência de rede.</td></tr>\n<tr><td><code>/api/admin/anp-bigquery-check</code></td><td>GET</td><td>admin</td><td>Verificação de acesso ao BigQuery da ANP.</td></tr>\n<tr><td><code>/api/webhooks/fiscal</code></td><td>POST</td><td><code>x-webhook-secret</code></td><td>Autorização ou rejeição de CT-e e MDF-e. Grava <code>fiscal_webhook_eventos</code> antes de processar; reprocessável.</td></tr>\n<tr><td><code>/api/webhooks/cobranca</code></td><td>POST</td><td><code>x-webhook-secret</code></td><td>Confirmação de pagamento do gateway de cobrança.</td></tr>\n<tr><td><code>/api/cron/sync-profrotas</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Sincroniza clientes com integração PróFrotas ativa (de hora em hora).</td></tr>\n<tr><td><code>/api/cron/atualizar-fipe</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Tabela FIPE (dia 1, 05:00).</td></tr>\n<tr><td><code>/api/cron/atualizar-precos-anp</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Variante via painel da atualização de preços ANP.</td></tr>\n<tr><td><code>/api/cron/auto-confirmar-fidelidade</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Confirmação automática de fidelidade (diária 06:00).</td></tr>\n<tr><td><code>/api/cron/conciliacao-automatica</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Conciliação bancária (diária 07:00).</td></tr>\n<tr><td><code>/api/cron/indicar-condutor-automatico</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Indica condutor em multas com candidato único (diária 07:15).</td></tr>\n<tr><td><code>/api/cron/gerar-insights-ia</code></td><td>GET, POST</td><td>CRON_SECRET</td><td>Insights diários por IA (05:00).</td></tr>\n</table>\n\n<h2 id=\"api-rpc\">9. RPCs Supabase</h2>\n<p>As RPCs são a API interna entre as aplicações e o banco: chamadas com <code>supabase.rpc(nome, args)</code>. São <code>SECURITY DEFINER</code> com <code>search_path = public</code> e conferem o usuário pelo e-mail do JWT. Hoje existem 373 funções no schema <code>public</code>; abaixo estão as do PDV (47, incluindo auxiliares) e as de base usadas por todos os apps. Funções com <code>anon</code> liberado ainda exigem usuário logado na prática, porque validam <code>empresas_do_usuario(auth.jwt() ->> 'email')</code>.</p>\n<h3 id=\"rpc-pdv\">9.1 RPCs do PDV</h3>\n<table>\n<tr><th>Função</th><th>Argumentos</th><th>Quem chama</th><th>O que faz</th></tr>\n<tr><td><code>buscar_revendas_pdv_proximas</code></td><td>lat, lon, raio_km</td><td>Motorista</td><td>Revendas com PDV ativo dentro do raio.</td></tr>\n<tr><td><code>iniciar_abastecimento_pdv</code></td><td>revenda_empresa_id, lat, lon, placa, hodometro</td><td>Motorista</td><td>Cria o abastecimento; valida geolocalização, vínculo e hodômetro. Existem 3 assinaturas (a com <code>p_hodometro</code> é a atual; as outras são legadas).</td></tr>\n<tr><td><code>obter_otp_atual_pdv</code></td><td>abastecimento_pdv_id</td><td>Motorista</td><td>OTP vigente (cálculo por semente, <code>otp_pdv_calcular</code>).</td></tr>\n<tr><td><code>status_abastecimento_pdv</code></td><td>abastecimento_pdv_id</td><td>Motorista</td><td>Situação para a tela de acompanhamento.</td></tr>\n<tr><td><code>avaliar_abastecimento_pdv</code></td><td>id, nota_posto, nota_abastecimento, nota_atendimento, observacao</td><td>Motorista</td><td>Avaliação pós-venda.</td></tr>\n<tr><td><code>contexto_hodometro_pdv</code></td><td>—</td><td>Motorista</td><td>Contexto para a captura do hodômetro (sem expor o último valor).</td></tr>\n<tr><td><code>meu_contexto_pdv</code></td><td>—</td><td>PDV</td><td>Revenda, perfil e terminal do usuário logado.</td></tr>\n<tr><td><code>listar_leituras_bomba_disponiveis_pdv</code></td><td>revenda_empresa_id</td><td>PDV</td><td>Leituras de bomba ainda sem abastecimento.</td></tr>\n<tr><td><code>registrar_leitura_bomba_pdv</code></td><td>id, terminal, bomba, bico, combustivel, litros, preco_litro</td><td>PDV / integração de bomba</td><td>Registra o que saiu da bomba.</td></tr>\n<tr><td><code>selecionar_leitura_bomba_pdv</code></td><td>id, leitura_id, terminal_id</td><td>PDV</td><td>Associa a leitura ao abastecimento.</td></tr>\n<tr><td><code>validar_codigo_abastecimento_pdv</code></td><td>codigo_abastecimento, otp</td><td>PDV</td><td>Valida código e OTP.</td></tr>\n<tr><td><code>validar_codigo_leitura_pdv</code></td><td>codigo_abastecimento, otp, leitura_id, terminal_id</td><td>PDV</td><td>Valida código, OTP e leitura numa chamada (fluxo atual, bomba primeiro).</td></tr>\n<tr><td><code>listar_formas_pagamento_permitidas_pdv</code></td><td>abastecimento_pdv_id</td><td>PDV</td><td>Formas aceitas pelo cliente daquele abastecimento.</td></tr>\n<tr><td><code>avaliar_regras_abastecimento_pdv</code></td><td>abastecimento_pdv_id, itens jsonb</td><td>interna (concluir)</td><td>Compara a venda com as regras do cliente. Devolve <code>violacoes</code> com <code>codigo</code>, <code>titulo</code>, <code>detalhe</code>, <code>corrigivel</code>.</td></tr>\n<tr><td><code>concluir_abastecimento_pdv</code></td><td>abastecimento_pdv_id, forma_pagamento, itens jsonb</td><td>PDV</td><td>Fecha a venda (ver tabela de respostas em 2.1).</td></tr>\n<tr><td><code>listar_abastecimentos_em_espera_pdv</code> · <code>dispensar_espera_pdv</code></td><td>revenda_empresa_id · abastecimento_pdv_id</td><td>PDV</td><td>Lista abastecimentos aguardando atendimento e permite dispensar a espera.</td></tr>\n<tr><td><code>listar_abastecimentos_negados_pdv</code> · <code>contar_abastecimentos_negados_pendentes_pdv</code></td><td>empresa_id</td><td>Cliente (web e PWA)</td><td>Fila de negados aguardando liberação e sua contagem.</td></tr>\n<tr><td><code>decidir_abastecimento_negado_pdv</code></td><td>abastecimento_pdv_id, decisao, justificativa</td><td>Cliente</td><td>Libera ou recusa um negado.</td></tr>\n<tr><td><code>consultar_pre_pedido_pdv</code> · <code>informar_pre_pedido_pdv</code></td><td>otp · id, otp</td><td>PDV</td><td>Consulta e vincula o pré-pedido ao abastecimento.</td></tr>\n<tr><td><code>iniciar_abastecimento_pre_pedido_pdv</code></td><td>codigo, leitura_id, terminal_pdv_id</td><td>PDV</td><td>Inicia abastecimento a partir do número do pré-pedido.</td></tr>\n<tr><td><code>limite_pre_pedido_abastecimento_pdv</code></td><td>abastecimento_pdv_id</td><td>interna</td><td>Limite do pré-pedido para validar a venda.</td></tr>\n<tr><td><code>buscar_voucher_pdv</code></td><td>empresa_id, codigo</td><td>PDV</td><td>Detalhes do voucher antes de queimar.</td></tr>\n<tr><td><code>queimar_voucher_fidelidade</code></td><td>empresa_id, codigo, origem, terminal_id</td><td>PDV</td><td>Queima o voucher e registra o valor a receber.</td></tr>\n<tr><td><code>listar_resgates_pdv</code></td><td>empresa_id, de, ate</td><td>PDV e web posto</td><td>Resgates do período com valor a receber e acerto.</td></tr>\n<tr><td><code>solicitar_ajuste_pdv</code></td><td>abastecimento_id, alteracoes jsonb, motivo, lado</td><td>Posto ou cliente</td><td>Cria pedido de ajuste (um pendente por abastecimento).</td></tr>\n<tr><td><code>decidir_ajuste_pdv</code></td><td>ajuste_id, aprovar, motivo</td><td>Contraparte</td><td>Aprova (aplica) ou recusa (motivo obrigatório).</td></tr>\n<tr><td><code>cancelar_ajuste_pdv</code></td><td>ajuste_id</td><td>Solicitante</td><td>Cancela pedido pendente.</td></tr>\n<tr><td><code>meus_ajustes_pdv</code></td><td>status, empresa_id</td><td>Posto e cliente</td><td>Lista de pedidos do usuário.</td></tr>\n<tr><td><code>contar_ajustes_pdv_pendentes_para_mim</code></td><td>—</td><td>Web, PDV, PWA Cliente</td><td>Quantos pedidos aguardam a decisão do usuário.</td></tr>\n<tr><td><code>metricas_pdv_dashboard</code></td><td>dias</td><td>PDV e web</td><td>Indicadores de uso.</td></tr>\n<tr><td><code>parametros_nf_abastecimento_pdv</code></td><td>abastecimento_pdv_id</td><td>PDV</td><td>Orientação de NF do abastecimento.</td></tr>\n<tr><td><code>ultimo_hodometro_veiculo</code></td><td>placa</td><td>legado</td><td>Devolve <code>null</code> (antifraude).</td></tr>\n<tr><td><code>ultimo_hodometro_veiculo_interno</code></td><td>placa</td><td>somente o banco</td><td>Sem acesso para anon e authenticated; usada pela validação.</td></tr>\n<tr><td><code>robo_teste_pdv_gerar_leitura_bomba</code> · <code>robo_teste_pdv_gerar_lote_leituras</code></td><td>…</td><td>testes</td><td>Simulam bomba para ambiente de teste.</td></tr>\n</table>\n<p><b>Gatilhos:</b> <code>creditar_pontos_abastecimento_pdv</code> (pontos ao confirmar), <code>registrar_ajuste_no_abastecimento_pdv</code> (copia status e motivo do ajuste para o abastecimento) e <code>notificar_ajuste_pdv_email</code> (chama <code>pdv-ajuste-email</code>). <b>Auxiliares internas:</b> <code>_pdv_grupo_combustivel</code>, <code>_pdv_prio_escopo</code>, <code>_pdv_viol</code>, <code>_pdv_servico_da_categoria</code>, <code>_pdv_registrar_falha_regra</code>, <code>distancia_metros_pdv</code>.</p>\n\n<h3 id=\"rpc-base\">9.2 RPCs de base</h3>\n<table>\n<tr><th>Função</th><th>Retorno</th><th>Uso</th></tr>\n<tr><td><code>empresas_do_usuario(p_email)</code></td><td><code>text[]</code></td><td>Empresas às quais o usuário pertence. Base da autorização de quase todas as RPCs.</td></tr>\n<tr><td><code>perfil_usuario_atual()</code></td><td><code>text</code></td><td>Perfil do usuário logado.</td></tr>\n<tr><td><code>nivel_perfil(p_perfil)</code></td><td><code>integer</code></td><td>admin 4 · gestor_frota 3 · analista 2 · posto 1 · demais 0.</td></tr>\n<tr><td><code>permissao_global_permitida(funcionalidade, perfil)</code></td><td><code>boolean</code></td><td>Consulta ao padrão global de permissões.</td></tr>\n<tr><td><code>resgatar_item_catalogo(item_id, dependente_id)</code></td><td><code>jsonb</code></td><td>Motorista troca pontos por benefício.</td></tr>\n<tr><td><code>aderencia_rede_negociada(empresa_cliente_id, dias)</code></td><td><code>jsonb</code></td><td>Fidelidade à rede negociada.</td></tr>\n<tr><td><code>abrir_negociacao_frete</code> · <code>propor_rodada_negociacao</code> · <code>aceitar_negociacao_frete</code> · <code>recusar_negociacao_frete</code></td><td><code>jsonb</code></td><td>Negociação de fretes.</td></tr>\n<tr><td><code>convidar_motorista_parceiro(empresa_id, motorista_id)</code></td><td><code>jsonb</code></td><td>Convite de motorista parceiro.</td></tr>\n<tr><td><code>atualizar_cache_precos_postos()</code></td><td>—</td><td>Recalcula o cache de preços (cron a cada 6 h).</td></tr>\n<tr><td><code>gerar_*_robo()</code></td><td>—</td><td>Robôs de teste e faturamento (ver seção 11).</td></tr>\n</table>\n<div class=\"note warn\">As demais ~300 funções (indicadores, financeiro, relatórios, frete, fiscal etc.) seguem o mesmo padrão. A lista completa e atualizada sai de <code>select proname, pg_get_function_identity_arguments(oid) from pg_proc where pronamespace = 'public'::regnamespace</code>. Os tipos TypeScript ficam em <code>src/types/database.types.ts</code> do painel.</div>\n\n<h2 id=\"api-edge\">10. Edge Functions</h2>\n<p>22 funções Deno no Supabase. <code>verify_jwt</code> ligado significa que o chamador precisa enviar um JWT válido (o pg_cron usa a chave anon guardada no vault, <code>supabase_anon_key_cron</code>).</p>\n<table>\n<tr><th>Função</th><th>JWT</th><th>Disparo</th><th>O que faz</th></tr>\n<tr><td><code>stripe-webhook</code></td><td>não</td><td>Webhook do Stripe</td><td>Recebe eventos de pagamento e assinatura.</td></tr>\n<tr><td><code>create-checkout-session</code></td><td>sim</td><td>Painel</td><td>Cria sessão de checkout do Stripe.</td></tr>\n<tr><td><code>create-billing-portal-session</code></td><td>sim</td><td>Painel</td><td>Abre o portal de cobrança do cliente.</td></tr>\n<tr><td><code>planos-precos</code></td><td>não</td><td>Painel e site</td><td>Lista planos e preços.</td></tr>\n<tr><td><code>email-trials</code></td><td>sim</td><td>cron diário 09:00</td><td>E-mails de ciclo de vida de trial.</td></tr>\n<tr><td><code>reportar-excedente-veiculos</code> · <code>-postos</code> · <code>-empresas-grupo</code></td><td>sim</td><td>cron diário 04:30 / 04:35 / 04:40</td><td>Reporta uso acima do plano.</td></tr>\n<tr><td><code>negociacao-email</code></td><td>sim</td><td>Painel / API</td><td>E-mail a cada rodada ou decisão de negociação.</td></tr>\n<tr><td><code>antifraude-email</code></td><td>sim</td><td>API antifraude</td><td>Avisa falha na verificação antifraude (fail-open).</td></tr>\n<tr><td><code>pdv-ajuste-email</code></td><td>sim</td><td>Gatilho em <code>pdv_ajustes</code></td><td>E-mail de pedido de ajuste (para o decisor) e de decisão (para o solicitante). Best-effort.</td></tr>\n<tr><td><code>frete-panico-email</code></td><td>sim</td><td>Gatilho de frete</td><td>Alerta de botão de pânico.</td></tr>\n<tr><td><code>alertas-sla-fretes</code></td><td>sim</td><td>cron a cada 30 min</td><td>Alerta de SLA de fretes.</td></tr>\n<tr><td><code>alertas-cadastros-pendentes</code></td><td>sim</td><td>cron seg 08:00</td><td>Cadastros pendentes.</td></tr>\n<tr><td><code>alertas-duplicidade-placas</code></td><td>sim</td><td>cron seg 08:15</td><td>Placas duplicadas.</td></tr>\n<tr><td><code>alertas-documentos-pendentes</code></td><td>sim</td><td>cron diário 08:30</td><td>Documentação parada.</td></tr>\n<tr><td><code>alertas-vencimentos</code></td><td>sim</td><td>cron diário 08:45</td><td>CNH, ASO, exames e apólices a vencer.</td></tr>\n<tr><td><code>atualizar-precos-anp</code></td><td>sim</td><td>cron seg 09:00 e ter 12:00 (UTC)</td><td>Atualiza preços ANP.</td></tr>\n<tr><td><code>atualizar-postos-anp</code></td><td>sim</td><td>cron ter 13:00 (UTC)</td><td>Atualiza o cadastro de postos ANP e grava <code>atualizado_em</code>.</td></tr>\n<tr><td><code>temp-criar-meter-posto</code> · <code>temp-criar-produtos-grupo-frota</code> · <code>temp-teste-conectividade-anp</code></td><td>sim / sim / não</td><td>manual</td><td>Funções temporárias de apoio. <b>Candidatas a remoção</b>: a de conectividade ANP está aberta sem JWT.</td></tr>\n</table>\n\n<h2 id=\"api-cron\">11. Rotinas agendadas (pg_cron)</h2>\n<p>25 rotinas. Horários em UTC; o horário de Brasília é 3 horas a menos.</p>\n<table>\n<tr><th>Rotina</th><th>Cron (UTC)</th><th>Alvo</th></tr>\n<tr><td>sync-profrotas-hourly</td><td><code>0 * * * *</code></td><td>/api/cron/sync-profrotas</td></tr>\n<tr><td>gerar-insights-ia-diario</td><td><code>0 5 * * *</code></td><td>/api/cron/gerar-insights-ia</td></tr>\n<tr><td>auto-confirmar-fidelidade</td><td><code>0 6 * * *</code></td><td>/api/cron/auto-confirmar-fidelidade</td></tr>\n<tr><td>conciliacao-automatica-diaria</td><td><code>0 7 * * *</code></td><td>/api/cron/conciliacao-automatica</td></tr>\n<tr><td>indicar-condutor-automatico-diario</td><td><code>15 7 * * *</code></td><td>/api/cron/indicar-condutor-automatico</td></tr>\n<tr><td>atualizar-fipe-mensal</td><td><code>0 5 1 * *</code></td><td>/api/cron/atualizar-fipe</td></tr>\n<tr><td>atualizar-precos-anp-semanal</td><td><code>0 9 * * 1</code></td><td>Edge atualizar-precos-anp</td></tr>\n<tr><td>atualizar-precos-anp-rede-seguranca-terca</td><td><code>0 12 * * 2</code></td><td>Edge atualizar-precos-anp</td></tr>\n<tr><td>atualizar-postos-anp-semanal</td><td><code>0 13 * * 2</code></td><td>Edge atualizar-postos-anp</td></tr>\n<tr><td>atualizar_cache_precos_postos</td><td><code>15 */6 * * *</code></td><td>SQL</td></tr>\n<tr><td>alertas-cadastros-pendentes-semanal · alertas-duplicidade-placas-semanal</td><td><code>0 8 * * 1</code> · <code>15 8 * * 1</code></td><td>Edge</td></tr>\n<tr><td>alertas-documentos-pendentes-diario · alertas-vencimentos-diario</td><td><code>30 8 * * *</code> · <code>45 8 * * *</code></td><td>Edge</td></tr>\n<tr><td>alertas-sla-fretes-cron</td><td><code>*/30 * * * *</code></td><td>Edge</td></tr>\n<tr><td>fni-email-trials</td><td><code>0 9 * * *</code></td><td>Edge</td></tr>\n<tr><td>reportar-excedente-veiculos / postos / empresas-grupo</td><td><code>30</code> / <code>35</code> / <code>40 4 * * *</code></td><td>Edge</td></tr>\n<tr><td>faturas_postos_robo · faturas_fretes_robo</td><td><code>0 3 * * *</code> · <code>30 3 1 * *</code></td><td>SQL</td></tr>\n<tr><td>robo_deteccao_acoes_sugeridas</td><td><code>0 9 * * *</code></td><td>SQL</td></tr>\n<tr><td>robo_abastecimentos_postos · robo_abastecimentos_meios_pagamento</td><td><code>0 */6 * * *</code></td><td>SQL (dados de teste)</td></tr>\n<tr><td>robo_notas_fiscais_teste</td><td><code>15 */6 * * *</code></td><td>SQL (dados de teste)</td></tr>\n</table>\n<pre class=\"mermaid\">\nflowchart LR\n  CR[\"pg_cron\"] -->|\"net.http_post + CRON_SECRET\"| W[\"Painel web /api/cron/*\"]\n  CR -->|\"net.http_post + chave anon do vault\"| E[\"Edge Functions\"]\n  CR -->|\"select função()\"| S[\"Funções SQL robô\"]\n  W --> DB[(\"Supabase\")]\n  E --> DB\n  S --> DB\n  E --> RS[\"Resend (e-mail)\"]\n  E --> ANP[\"ANP\"]\n</pre>\n\n<h2 id=\"api-terc\">12. Integrações externas</h2>\n<table>\n<tr><th>Serviço</th><th>Direção</th><th>Usado em</th><th>Como autentica</th></tr>\n<tr><td><b>PróFrotas</b></td><td>FNI puxa</td><td>Sync horário de abastecimentos por cliente</td><td>Token do parceiro guardado por cliente</td></tr>\n<tr><td><b>Provedores de cartão</b> (Ticket Log, Alelo, Repom…)</td><td>Parceiro empurra</td><td><code>/api/integracoes/abastecimentos</code> e faturas</td><td>Chave de API do cliente</td></tr>\n<tr><td><b>ERPs de posto</b> (Tanknomia, SAT…)</td><td>Parceiro empurra</td><td>Abastecimentos fornecidos, NF-e, negociações</td><td>Chave de API do posto</td></tr>\n<tr><td><b>Provedores de GPS</b> (Sascar, Positron, Onixsat…)</td><td>Parceiro empurra</td><td><code>/api/integracoes/gps</code></td><td>Chave de API do cliente</td></tr>\n<tr><td><b>ANP</b></td><td>FNI puxa</td><td>Preços e cadastro de postos</td><td>Dados públicos; BigQuery verificado em <code>/api/admin/anp-bigquery-check</code></td></tr>\n<tr><td><b>Stripe</b></td><td>Ambos</td><td>Assinaturas e cobrança</td><td>Chave secreta (Edge) e assinatura do webhook</td></tr>\n<tr><td><b>Resend</b></td><td>FNI envia</td><td>E-mails de Edge Functions e alertas</td><td>Chave de API nos secrets da Edge</td></tr>\n<tr><td><b>Anthropic</b></td><td>FNI chama</td><td>Assistente FNI e insights de IA</td><td><code>ANTHROPIC_API_KEY</code> só no servidor</td></tr>\n<tr><td><b>FIPE</b></td><td>FNI puxa</td><td>Valor de veículos</td><td>Dados públicos</td></tr>\n<tr><td><b>Provedor fiscal</b> (CT-e, MDF-e) e <b>gateway de cobrança</b></td><td>Webhook entra</td><td><code>/api/webhooks/fiscal</code> e <code>/cobranca</code></td><td><code>x-webhook-secret</code></td></tr>\n<tr><td><b>UptimeRobot → Teams</b></td><td>Webhook entra</td><td>Alertas de indisponibilidade</td><td>Segredo na URL</td></tr>\n<tr><td><b>Tesseract.js (OCR)</b></td><td>No servidor</td><td>Hodômetro, cupom, CT-e/canhoto</td><td>Sem chave (biblioteca local)</td></tr>\n<tr><td><b>Railway</b></td><td>Hospedagem</td><td>Painel, PDV e PWAs; deploy automático e health check</td><td>—</td></tr>\n</table>\n\n<h2 id=\"glossario\">13. Glossário e pendências</h2>\n<table>\n<tr><th>Termo</th><th>Significado</th></tr>\n<tr><td>PDV</td><td>Frente de caixa do posto (aplicação <code>pdv-fni</code>).</td></tr>\n<tr><td>OTP</td><td>Senha de uso único gerada por semente, renovada a cada poucos segundos, que o motorista mostra ao caixa.</td></tr>\n<tr><td>Código do abastecimento</td><td><code>4000000000 + id</code> do registro em <code>abastecimentos_pdv</code>.</td></tr>\n<tr><td>Negado</td><td>Abastecimento barrado por regra do cliente, aguardando liberação.</td></tr>\n<tr><td>Pré-Pedido</td><td>Rota de paradas por veículo, com limites e número de 6 dígitos por parada.</td></tr>\n<tr><td>Escopo (de chave)</td><td>Permissão de uma chave de API, no padrão <code>recurso:acao</code>.</td></tr>\n<tr><td>Sentinela global</td><td>Empresa <code>00000000-…</code> que guarda o padrão de permissões.</td></tr>\n</table>\n<h4>Pendências conhecidas (para manter a documentação fiel)</h4>\n<ul>\n<li>Deploy do commit <code>7d023fc</code> (pdv-fni) e dos pushes do Gestão de Frotas e estudo-de-rede.</li>\n<li>Decisão de pedido de ajuste direto no PWA Cliente (hoje abre o painel web).</li>\n<li>Caixa que abre o painel web cai em telas bloqueadas; falta redirecionar para o PDV.</li>\n<li>Remover as três Edge Functions <code>temp-*</code>.</li>\n<li>Colaboradores antigos de empresas clientes continuam como colaborador (não aparecem na matriz do gestor).</li>\n<li>Validar execução da rotina de postos ANP de 06/10 (<code>anp_postos.atualizado_em</code>).</li>\n<li>Os nomes exatos dos estados do abastecimento PDV devem ser conferidos no banco antes de usar em contratos externos (ver nota em 2.1).</li>\n</ul>\n</main>\n<script src=\"/vendor/mermaid.min.js\"></script>\n<script>\nmermaid.initialize({startOnLoad:true,theme:'default',securityLevel:'loose',flowchart:{htmlLabels:true,useMaxWidth:true},sequence:{useMaxWidth:true}});\nfunction filtra(q){q=q.toLowerCase();document.querySelectorAll('aside a').forEach(a=>{a.style.display=a.textContent.toLowerCase().includes(q)?'':'none'})}\n</script>\n</body>\n</html>\n";
